<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Customer,PaymentReceived,PaymentAllocation,SalesInvoice}; use App\Services\{AuthorizationService,SalesDocumentService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class PaymentController { public function index(){return response()->json(['data'=>PaymentReceived::where('tenant_id',app(TenantContext::class)->id())->latest()->paginate(25)]);} public function store(Request $r,AuthorizationService $a){$t=app(TenantContext::class)->id();abort_unless($a->allows($r->user(),$t,'sales.manage'),403);$d=$r->validate(['customer_id'=>'required|uuid','reference'=>'required|string|max:100','method'=>'required|string|max:40','amount'=>'required|numeric|gt:0']);abort_unless(Customer::where('tenant_id',$t)->whereKey($d['customer_id'])->exists(),404);return response()->json(['data'=>PaymentReceived::create([...$d,'tenant_id'=>$t,'received_by'=>$r->user()->id,'state'=>'pending_verification'])],201);} public function verify(Request $r,PaymentReceived $payment,SalesDocumentService $state){$this->own($payment);$state->transition($payment,'payment','verified',$r->user()->id);$payment->update(['verified_at'=>now(),'verified_by'=>$r->user()->id]);event(new \App\Events\PaymentVerifiedForAccounting($payment->tenant_id,$payment->id,$payment->customer_id,(string)$payment->amount));return response()->json(['data'=>$payment->fresh()]);} public function allocate(Request $r,PaymentReceived $payment){$this->own($payment);abort_unless($payment->state==='verified',422,'Only verified payments may be allocated.');$d=$r->validate(['invoice_id'=>'required|uuid','amount'=>'required|numeric|gt:0']);$allocation=DB::transaction(function()use($d,$payment){$invoice=SalesInvoice::where('tenant_id',$payment->tenant_id)->whereKey($d['invoice_id'])->lockForUpdate()->firstOrFail();abort_unless($invoice->customer_id===$payment->customer_id,422,'Payment customer does not match invoice customer.');$allocated=PaymentAllocation::where('payment_id',$payment->id)->sum('amount');$remainingPayment=Decimal::sub((string)$payment->amount,(string)$allocated);$remainingInvoice=Decimal::sub((string)$invoice->total,(string)$invoice->paid_total);$amount=Decimal::normalize((string)$d['amount']);if(Decimal::compare($amount,$remainingPayment)>0||Decimal::compare($amount,$remainingInvoice)>0)throw ValidationException::withMessages(['amount'=>['Allocation exceeds available payment or invoice balance.']]);$a=PaymentAllocation::create(['tenant_id'=>$payment->tenant_id,'payment_id'=>$payment->id,'invoice_id'=>$invoice->id,'amount'=>$amount]);$invoice->update(['paid_total'=>Decimal::add((string)$invoice->paid_total,$amount),'state'=>Decimal::compare(Decimal::add((string)$invoice->paid_total,$amount),(string)$invoice->total)>=0?'paid':'partially_paid']);return $a;});return response()->json(['data'=>$allocation],201);} private function own(PaymentReceived $p):void{abort_unless($p->tenant_id===app(TenantContext::class)->id(),404);} }
